int read_from_socket(int s, void* arg, int* len) {
    int header;
    if (recv(s, &header, sizeof(header), 0) <= 0) {
        return -1;
    }

    // Extract length and type from header
    int data_length = (header >> 8) & 0x00FFFFFF;
    int data_type = header & 0xFF;

    if (data_length <= 0) {
        *len = 0;
        return data_type;
    }

    if (data_length > *len) {
        *len = 0;
        return -1; // Buffer is too small
    }

    if (recv(s, arg, data_length, 0) <= 0) {
        return -1;
    }

    *len = data_length;
    return data_type;
}

int read_socket_data(int s, void* arg, int* len) {
    int header;
    if (recv(s, &header, sizeof(header), 0) <= 0) {
        return -1;
    }

    if (header <= 0 || header > 1024) {
        return -1;
    }

    if (*len < header) {
        *len = header;
    }

    int data_type = *(int*)arg;
    if (recv(s, arg, header, 0) <= 0) {
        return -1;
    }

    *len = header;
    return data_type;
}

int read_socket_data(int s, void* arg, int* len) {
    int data_type;
    ssize_t bytes_read;

    // Read the data type
    bytes_read = read(s, &data_type, sizeof(int));
    if (bytes_read != sizeof(int)) {
        return -1; // Error reading data type
    }

    // Read the length of the incoming data
    int data_len;
    bytes_read = read(s, &data_len, sizeof(int));
    if (bytes_read != sizeof(int)) {
        return -1; // Error reading data length
    }

    // Check if the length is valid
    if (data_len < 0) {
        return -1; // Invalid length
    }

    // Update the provided length
    if (*len < data_len) {
        *len = 0; // Buffer is too small
    } else {
        *len = data_len;
    }

    // If length is greater than zero, read the actual data
    if (data_len > 0) {
        bytes_read = read(s, arg, data_len);
        if (bytes_read != data_len) {
            return -1; // Error reading data
        }
    }

    return data_type;
}

int read_socket_data(int s, void* arg, int* len) {
    int header;
    if (recv(s, &header, sizeof(int), 0) <= 0) {
        return -1;
    }

    int data_length = ntohl(header);
    if (data_length < 0) {
        return -1;
    }

    if (len != NULL) {
        if (data_length > *len) {
            return -1;  // Buffer is too small for incoming data
        }
        *len = data_length;
    }

    if (data_length > 0 && arg != NULL) {
        if (recv(s, arg, data_length, 0) <= 0) {
            return -1;
        }
    }

    return data_length;
}

int read_socket_data(int s, void* arg, int* len) {
    int header;
    if (recv(s, &header, sizeof(int), 0) <= 0) {
        return -1;
    }

    int data_length = ntohl(header);
    if (data_length < 0) {
        return -1;
    }

    if (len != NULL) {
        *len = data_length;
    }

    if (data_length > 0) {
        int bytes_received = recv(s, arg, data_length, 0);
        if (bytes_received <= 0) {
            return -1;
        }
    }

    int data_type;
    if (recv(s, &data_type, sizeof(int), 0) <= 0) {
        return -1;
    }

    return data_type;
}
